/* ===========================================================================
   SCIENTIFIC PANEL — task 2. Everything below is scoped to #panel-scientific
   and reuses the shared primitives (.panel .cols .stack .row .readout__value
   .keypad .key .chip .btn .sr-only). Two local tokens are declared inside the
   panel scope rather than in the shared :root block:
     --sci-alert (#f0938a, 8.0:1 on --panel) for error copy and the caret,
     --sci-well  (recessed glass) for the display and the angle switch.
   =========================================================================== */
#panel-scientific {
  --sci-alert: #f0938a;
  --sci-alert-edge: rgba(240, 147, 138, 0.45);
  --sci-well: rgba(10, 15, 15, 0.62);
}

/* ---------- display ---------- */
.sci__display {
  position: relative;
  padding: var(--sp-3) var(--sp-3) calc(var(--sp-2) + 0.15rem);
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  background-image: linear-gradient(180deg, rgba(240, 234, 221, 0.035), transparent 42%);
  background-color: var(--sci-well);
}

.sci__expr {
  margin: 0;
  min-height: 1.7em;
  font-family: var(--font-mono);
  font-size: 1.02rem;
  line-height: 1.7;
  color: var(--bone);
  overflow-wrap: anywhere;
  word-break: break-word;
}
.sci__expr-body { white-space: pre-wrap; }

.sci__tok-num { color: var(--bone); }
.sci__tok-name { color: var(--dim); }
.sci__tok-paren { color: var(--dim); }
.sci__tok-op { color: var(--accent); }
.sci__tok-bad { color: var(--sci-alert); border-bottom: 1px dotted var(--sci-alert-edge); }

.sci__caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-right: 1px;
  vertical-align: -0.15em;
  background: var(--accent);
  animation: sci-caret 1.15s steps(1, end) infinite;
}
@keyframes sci-caret {
  0%, 50% { opacity: 1; }
  50.01%, 100% { opacity: 0; }
}

.sci__placeholder {
  margin-left: 0.45em;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--dim);
  opacity: 0.72;
}

.sci__hero {
  display: grid;
  gap: 0.1rem;
  margin-top: 0.4rem;
  padding-top: 0.6rem;
  border-top: 1px solid var(--rule-soft);
}
.sci__figure {
  display: flex;
  align-items: baseline;
  gap: 0.14em;
  min-height: 1.05em;
  margin: 0;
  font-size: clamp(1.8rem, 4.4vw, 3rem);
  transition: color 0.25s var(--ease), opacity 0.25s var(--ease);
}
.sci__figure-text { min-width: 0; overflow-wrap: anywhere; }
.sci__figure--preview { color: var(--dim); }
.sci__figure--empty { color: var(--dim); opacity: 0.45; }
.sci__figure--stale { color: var(--dim); opacity: 0.35; }
.sci__approx {
  font-size: 0.4em;
  line-height: 1;
  color: var(--dim);
  transform: translateY(-0.75em);
}
.sci__exp {
  font-family: var(--font-mono);
  font-size: 0.4em;
  letter-spacing: 0;
  color: var(--dim);
  white-space: nowrap;
}
.sci__exp sup { font-size: 0.78em; line-height: 0; }

.sci__msg {
  margin: 0.6rem 0 0;
  padding-left: 0.6rem;
  border-left: 2px solid var(--sci-alert);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.5;
  color: var(--sci-alert);
}

.sci__chips { margin-top: 0.75rem; gap: 0.4rem; }
.sci__chips .chip { text-transform: none; }

/* ---------- keys ---------- */
.sci__keys { display: grid; gap: var(--sp-3); }

.sci__strip {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.45rem;
}

.sci__group { display: grid; gap: 0.4rem; }
.sci__group-label {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.03em;
  color: var(--dim);
}
.sci__group-label::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--rule-soft);
}

.sci .keypad--fn { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0.4rem; }
.sci .keypad--num { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0.5rem; }

.sci .key--tiny { min-height: 2.45rem; font-size: 0.76rem; letter-spacing: 0.01em; }
.sci .key--edit { color: var(--dim); }
.sci .key--edit:hover { color: var(--bone); }
.sci .key--fn { min-height: 2.85rem; font-size: 0.84rem; }
.sci .key--num { min-height: 3.4rem; font-size: 1.08rem; }
.sci .key--zero { grid-column: span 2; }
.sci .key--equals {
  grid-column: 1 / -1;
  min-height: 3.3rem;
  font-size: 1.15rem;
  letter-spacing: 0.05em;
}

.sci__legend {
  display: grid;
  gap: 0.3rem;
  padding-top: var(--sp-2);
  border-top: 1px solid var(--rule-soft);
}
.sci__legend-line {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  line-height: 2;
  color: var(--dim);
}
.sci__legend kbd {
  font: inherit;
  padding: 0.02rem 0.32rem;
  border: 1px solid var(--rule);
  border-radius: 3px;
  color: var(--bone);
}

/* ---------- side column: angles, tape, notes ---------- */
.sci__side { gap: var(--sp-4); align-content: start; }
.sci__block { display: grid; gap: 0.55rem; }
.sci__block + .sci__block {
  padding-top: var(--sp-3);
  border-top: 1px solid var(--rule);
}
.sci__block-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.4rem 0.75rem;
}
.sci__block-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
  color: var(--bone);
}
.sci__note {
  margin: 0;
  max-width: 36ch;
  font-size: 0.86rem;
  line-height: 1.5;
  color: var(--dim);
}
.sci__footnote {
  margin: 0;
  max-width: 34ch;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  line-height: 1.7;
  color: var(--dim);
}

.seg {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  background: var(--sci-well);
  width: fit-content;
}
.seg__btn {
  min-height: 2rem;
  padding: 0.25rem 0.7rem;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--dim);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: color 0.18s var(--ease), background-color 0.18s var(--ease),
    box-shadow 0.18s var(--ease);
}
.seg__btn:hover { color: var(--bone); }
.seg__btn[aria-pressed="true"] {
  background: var(--accent-tint);
  color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent-edge);
}

.tape {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  max-height: 16rem;
  overflow-y: auto;
  scrollbar-width: thin;
  border-top: 1px solid var(--rule-soft);
}
.tape:empty { display: none; }
.tape__item { border-bottom: 1px solid var(--rule-soft); }
.tape__entry {
  display: grid;
  gap: 0.1rem;
  width: 100%;
  padding: 0.5rem 0.4rem;
  border: 0;
  background: transparent;
  text-align: left;
  font-family: var(--font-mono);
  color: var(--bone);
  cursor: pointer;
  transition: background-color 0.16s var(--ease);
}
.tape__entry:hover { background: var(--accent-tint); }
.tape__expr {
  font-size: 0.76rem;
  color: var(--dim);
  overflow-wrap: anywhere;
}
.tape__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
}
.tape__value {
  font-size: 0.92rem;
  color: var(--bone);
  overflow-wrap: anywhere;
}
.tape__angle {
  font-size: 0.66rem;
  letter-spacing: 0.05em;
  color: var(--dim);
  white-space: nowrap;
}

.sci .btn--small {
  padding: 0.25rem 0.55rem;
  font-size: 0.8rem;
}

/* the keypad lives under a thumb on small screens */
@media (max-width: 1080px) {
  #panel-scientific .cols--wide { grid-template-columns: minmax(0, 1fr); }
  .sci__side { gap: var(--sp-3); }
}
@media (max-width: 540px) {
  .sci__display { padding: var(--sp-2); }
  .sci__figure { font-size: clamp(1.6rem, 8vw, 2.4rem); }
  .sci .keypad--fn { gap: 0.3rem; }
  .sci .keypad--num { gap: 0.4rem; }
  .sci .key--fn { min-height: 2.6rem; font-size: 0.76rem; }
  .sci .key--num { min-height: 3rem; font-size: 1rem; }
  .sci .key--tiny { min-height: 2.2rem; font-size: 0.7rem; }
  .sci__strip { gap: 0.3rem; }
}
@media (prefers-reduced-motion: reduce) {
  .sci__caret { animation: none; opacity: 1; }
}

  // ==== LOGIC: scientific ====
  /* ------------------------------------------------------------------
     SCIENTIFIC — engine and instrument.

     tokeniser -> implicit multiplication -> shunting-yard -> RPN evaluator.
     Hand written on purpose: no eval(), no new Function(), nothing external.
     The tokeniser and evaluator are exposed as SciEngine so the graph
     register can reuse them for f(x) later.
     ------------------------------------------------------------------ */
  var SciEngine = (function () {
    var HIGH = 1e10;   /* above this magnitude the figure switches to a power of ten */
    var LOW = 1e-7;    /* below this one too */
    var DIGITS = 12;   /* significant figures kept, which trims floating point noise */

    var RAD = { deg: Math.PI / 180, rad: 1, grad: Math.PI / 200 };
    var INV = { deg: 180 / Math.PI, rad: 1, grad: 200 / Math.PI };

    var CONSTANTS = { pi: Math.PI, e: Math.E };

    /* kind: 'hard' stops the calculation, 'incomplete' means more is still to
       come (quiet while typing), 'soft' is most likely a half-typed word. */
    function fail(message, kind) {
      var err = new Error(message);
      err.calc = true;
      err.kind = kind || 'hard';
      return err;
    }

    var FUNCS = {
      sin: function (x, m) { return Math.sin(x * RAD[m]); },
      cos: function (x, m) { return Math.cos(x * RAD[m]); },
      tan: function (x, m) {
        var r = x * RAD[m];
        if (Math.abs(Math.cos(r)) < 1e-12) {
          throw fail('tan has no value at that angle. Try one a quarter turn away.');
        }
        return Math.tan(r);
      },
      asin: function (x, m) {
        if (!(x >= -1 && x <= 1)) throw fail('asin only reads numbers from -1 to 1.');
        return Math.asin(x) * INV[m];
      },
      acos: function (x, m) {
        if (!(x >= -1 && x <= 1)) throw fail('acos only reads numbers from -1 to 1.');
        return Math.acos(x) * INV[m];
      },
      atan: function (x, m) { return Math.atan(x) * INV[m]; },
      ln: function (x) {
        if (!(x > 0)) throw fail('ln only reads numbers above zero.');
        return Math.log(x);
      },
      log: function (x) {
        if (!(x > 0)) throw fail('log only reads numbers above zero.');
        return Math.log(x) / Math.LN10;
      },
      sqrt: function (x) {
        if (x < 0) throw fail('The square root of a negative number is not a real number. Try abs first.');
        return Math.sqrt(x);
